'use client';

import { useState } from 'react';
import UserStats from './UserStats';

export default function Page() {
  const [users, setUsers] = useState([
    { id: 1, name: 'John', isActive: true },
    { id: 2, name: 'Jane', isActive: false },
    { id: 3, name: 'Bob', isActive: true }
  ]);

  // ✓ GOOD EXAMPLE: Derived value calculated directly
  const totalUsers = users.length;

  return (
    <div>
      <h1>User Management</h1>
      <p>Total Users: {totalUsers}</p>

      <div>
        {users.map(user => (
          <div key={user.id}>
            {user.name} - {user.isActive ? 'Active' : 'Inactive'}
          </div>
        ))}
      </div>

      <UserStats users={users} />
    </div>
  );
}
```

**Key Pattern:** The codebase uses **direct calculation of derived values** at the component level:
- No Redux or external state management
- No useMemo or useCallback (not needed for simple calculations)
- Simple variable assignment: `const totalUsers = users.length;`
- Values recalculate on each render (efficient for this use case)

